// src/components/styles/readaloud.scss
var readaloud_default = ".bwz-ra {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 0.5rem 0.75rem;\n  margin: 0 0 1rem;\n  padding: 0.6rem 0.75rem;\n  border: 1px solid var(--lightgray);\n  border-radius: 10px;\n  background: var(--light);\n  background: color-mix(in srgb, var(--secondary) 12%, transparent);\n  color: var(--darkgray);\n  font-family: var(--bodyFont);\n  line-height: 1.4;\n}\n.bwz-ra > span {\n  color: var(--dark);\n  font-family: var(--headerFont);\n  font-weight: 700;\n}\n.bwz-ra label {\n  display: inline-flex;\n  align-items: center;\n  gap: 0.35rem;\n}\n.bwz-ra button,\n.bwz-ra select {\n  min-height: 36px;\n  border: 1px solid var(--lightgray);\n  border-radius: 7px;\n  background: var(--light);\n  color: var(--darkgray);\n  font: inherit;\n}\n.bwz-ra button {\n  padding: 0.35rem 0.75rem;\n  cursor: pointer;\n}\n.bwz-ra button:hover {\n  border-color: var(--gray);\n}\n.bwz-ra button:focus-visible {\n  outline: 2px solid var(--secondary);\n  outline-offset: 2px;\n}\n.bwz-ra select {\n  padding: 0.25rem 0.5rem;\n}\n.bwz-ra select:focus-visible {\n  outline: 2px solid var(--secondary);\n  outline-offset: 2px;\n}\n.bwz-ra.is-playing {\n  position: sticky;\n  top: 0;\n  z-index: 5;\n}\n\n.bwz-verses > li.bwz-ra-now,\nol > li.bwz-ra-now {\n  border-left: 3px solid var(--secondary);\n  background-color: color-mix(in srgb, var(--highlight) 55%, var(--light));\n  transition: background-color 150ms ease, border-color 150ms ease;\n}\n\n@media (max-width: 600px) {\n  .bwz-ra {\n    align-items: stretch;\n  }\n  .bwz-ra > span {\n    flex-basis: 100%;\n  }\n  .bwz-ra label,\n  .bwz-ra button {\n    flex: 1 1 8rem;\n  }\n}\n@media (prefers-reduced-motion: reduce) {\n  .bwz-verses > li.bwz-ra-now,\n  ol > li.bwz-ra-now {\n    transition: none;\n  }\n}";

